import{a as e,i as t,s as n,t as r}from"./app-CchzzT6L.js";var i=JSON.parse(`{"path":"/ML/","title":"GAN","lang":"en-US","frontmatter":{},"git":{"updatedTime":1615746745000,"contributors":[{"name":"Noei","username":"Noei","email":"logmanxsa@gmail.com","commits":2,"url":"https://github.com/Noei"}],"changelog":[{"hash":"65466cdbf81e444a3c55aea49f6acbabf34bd61a","time":1615746745000,"email":"logmanxsa@gmail.com","author":"Noei","message":"ML test content"},{"hash":"cf9e4ac6fdf08c5bb2d9de582ba68ab42fecd850","time":1611550573000,"email":"logmanxsa@gmail.com","author":"Noei","message":"Demo HCK ML"}]},"filePathRelative":"ML/README.md"}`),a={name:`README.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="gan" tabindex="-1"><a class="header-anchor" href="#gan"><span>GAN</span></a></h1><ul><li>ปกติถ้าจะ train AI ให้ได้ซักตัวตัวเนี่ยเรามักจะมีโจทย์พร้อมกับเฉลยให้มัน เช่น การบอกว่าลูกสีแดงมีส่วนเว้านบนล่างข้างในเป็นสีขาว คำตอบคือ แอปเปิ้ลไรประมาณนี้ หรือไม่ก็เอาโหลดภาพ Apple เข้าไปให้มันดูแล้วบอกว่าเนี่ยคือ Apple</li><li>ซื่งในงานจริง ๆ ใช้ข้อมูลเยอะมาก ๆ อย่างในต่างประเทศถึงกับมีอาชีพหนึ่งเลยชื่อ นักเทรน AI เค้าเปิดห้องใหญ่แล้วจ้างคนไปนั่งเทรนให้ AI เลยแต่ผมจำไม่ได้ละว่าเทรน AI อะไร</li><li>ที่นี้เรากลับมาหา GAN กันครับ<br> GAN เป็นเทคโนโลยีที่อยู่เบื้องหลังพวก DeepFake สร้างใบหน้าปลอมหรือจะเป็น FaceApp ที่สร้างหน้าเราตอนแก่ขึ้นมาซึ่งเคยเป็น viral อยู่ช่วงหนึ่งใน social<br> โดย GAN เนี่ยมันไม่ต้องพึ่งพามนุษย์เลยในการเรียนรู้เลย การทำงานของมันจะเป็นแบบนี้ครับ<br> จะมี AI อยู่ 2 ตัว</li><li>ตัวแรกคือ Generator หน้าที่ของมันก็คือสร้างข้อมูลปลอมขึ้นมาเพื่อหลอก AI อีกตัวตอบผิดให้ได้มากที่สุด</li><li>ตัวที่สองคือ Discriminator หน้าที่ของมันก็คือแยกข้อมูลจริงกับข้อมูลปลอมที่ถูก Generate ขึ้นมา และพยายามทายให้ถูกต้องมากที่สุด <br><br> มาดูการทำงานของ GAN กัน</li><li>อย่างแรกเลยเราจะ input ข้อมูลให้มันก่อนครับซึ่งข้อมูลนี้จะเป็นไรก็ได้ เช่น รูป หรือ เสียง ได้หมดเลย</li><li>ในวันนี้ผมจะยกตัวอย่างข้อมูลชนิดรูปภาพ เอาเป็นรูปแอปเปิ้ลแล้วกัน ทีนี้เรามาเริ่มดูการทำงานมันครับ</li><li>มาเริ่มที่ Generator ก่อนเลยก็คือ Genterator เนี่ยมันจะสร้างภาพปลอมขึ้นมาโดย Random ข้อมูลออกมาเป็นภาพ Noise มั่ว ๆ ไปหมดเลย</li><li>แล้วก็ส่งไปให้ Discriminator ครับ Discriminator ก็จะวิเคราะห์ดูว่าข้อมูลนั้นเป็นของจริงหรือปลอมโดยอ้างอิงจากภาพที่เรา input เข้าไป แล้วก็ Feedback กลับไปให้ Generator</li><li>พอ Generator ได้รับ Feedback จาก Discriminator มันก็จะเป็นข้อมูลตรงนั้นมาปรับ ปรับภาพข้อมูลปลอมให้เสมือนจริงมากยิ่งขึ้น แล้วก็ส่งไปหลอก Discriminator อีก โดยทั้งสองตัวจะนำ Feedback ที่ส่งให้กัน ไปปรับปรุงตัวเองให้ดียิ่งเรื่อย ๆ</li><li>มันทำอย่างงี้วนไปวนมากจนทั้งคู่มาถึงจุดที่ level ตันครับ ไม่สามารถ upskill ต่อไปได้ละ ก็เป็นอันสิ้นสุดพร้อมเอาไปใช้งานครับ</li><li>ตัวที่จะถูกนำไปใช้งานก็คือ Generator ครับอย่างพวก Deepfake หรือ FaceApp ที่พูดไปตอนต้นก็ล้วนมาจากฝีมือของเจ้า Generator เนี่ยแหละครับ <br><br></li><li>จะเห็นว่าการที่เราให้ AI สองตัวมันช่วยกันทำงาน ตัวหนึ่งช่วยแนะนำและแก้ข้อผิดพลาดให้อีกตัวหนึ่ง นั่นก็หมายความว่าพวกมันไม่ต้องพึ่งพามนุษย์เลยในการเรียนรู้ ซึ่งจะนำไปสู่ยุคที่ AI จะครองโลกและมนุษย์ไม่มีที่อยู่ในสังคมอีกต่อไปครับ</li></ul><p>https://make.girls.moe/#/ Feature Sketch ภาพกล้องถ่ายภาพโดเรม่อน</p>`,3)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};